            for k in a:
                if k not in b:
                    emit('test', path + [k], a[k])
                    emit('remove', path + [k], a[k])
            for k in b:
                if k not in a:
                    emit('add', path + [k], b[k])
                else:
                    walk(a[k], b[k], path + [k])
            return
        if isinstance(a, list) and isinstance(b, list):
